<?php session_start();require_once __DIR__.'/../../src/db.php';require_once __DIR__.'/../../src/upload.php';if(!($_SESSION['admin']??false)){header('Location:/admin/');exit;}$err='';if($_SERVER['REQUEST_METHOD']==='POST'){try{if(!isset($_FILES['image'])||$_FILES['image']['error'])throw new RuntimeException('Выберите изображение');$f=$_FILES['image'];$projection=in_array($_POST['projection']??'', ['flat','180','360'],true)?$_POST['projection']:'360';$stereo=in_array($_POST['stereo']??'', ['mono','sbs','tb'],true)?$_POST['stereo']:'mono';$name=storeUploadedImage($f,UPLOAD_DIR);$title=trim($_POST['title']);$slug=preg_replace('/[^a-z0-9]+/','-',strtolower($_POST['slug']?:bin2hex(random_bytes(4))));$q=db()->prepare("INSERT INTO panoramas(title,slug,description,image,projection,stereo,published) VALUES(?,?,?,?,?,?,?)");$q->execute([$title,$slug,trim($_POST['description']),'/uploads/'.$name,$projection,$stereo,isset($_POST['published'])?1:0]);header('Location:/admin/');exit;}catch(Throwable $e){$err=$e->getMessage();}}?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><link rel="stylesheet" href="/assets/admin.css"></head><body><aside><div class="logo">MINI<span>VR</span></div><a href="/admin/">← Материалы</a></aside><main><header><div><small>NEW VR ASSET</small><h1>Новый материал</h1></div></header><?php if($err):?><div class="error"><?=htmlspecialchars($err)?></div><?php endif;?><form class="editor" method="post" enctype="multipart/form-data"><label>Название<input name="title" required placeholder="Главный зал"></label><label>Slug<input name="slug" placeholder="main-hall"></label><label>Проекция<select name="projection"><option value="360">360° equirectangular</option><option value="180">180° panorama</option><option value="flat">Плоское изображение</option></select></label><label>Стерео<select name="stereo"><option value="mono">Mono</option><option value="sbs">Stereo SBS — Left | Right</option><option value="tb">Stereo Top / Bottom</option></select></label><label>Описание<textarea name="description" rows="5"></textarea></label><label class="drop">VR IMAGE ASSET<input type="file" name="image" accept="image/jpeg,image/png,image/webp" required><span>JPG / WEBP / PNG • mono / SBS / Top-Bottom</span></label><label class="check"><input type="checkbox" name="published" checked> Опубликовать сразу</label><button class="btn">СОХРАНИТЬ →</button></form></main></body></html>